import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateQuiz } from "../handlers/updateQuiz";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpaceQuizEntityType } from "../types/SpaceQuizEntityType";
import type { UpdateQuizRequest } from "../types/UpdateQuizRequest";

type Data = Awaited<ReturnType<typeof updateQuiz>>;
type Vars = { spacePk: SpacePartition; quizId: SpaceQuizEntityType; req: UpdateQuizRequest };

export function useUpdateQuiz(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateQuiz(vars.spacePk, vars.quizId, vars.req),
    ...options,
  });
}
